    #[test]
    fn workspace_transition_is_prepare_durable_commit_and_missing_initialized_state_fails_closed() {
        let repository = source("com/ofairyo/gridtimer/data/TimerRepository.kt");
        assert!(repository.contains("state_initialization_evidence"));
        assert!(repository.contains("writeWorkspaceInitializationEvidence(workspaceKey)"));
        assert!(repository.contains("workspaceWasPreviouslyInitialized(workspaceKey, files)"));
        assert!(repository
            .contains("检测到工作区曾经初始化，但当前快照与镜像均缺失，已禁止重建为空数据"));
        assert!(repository
            .contains("Do not manufacture an \"already initialized\" marker on a true first"));
        assert!(repository.contains("loadPersistedDataForWorkspace(targetWorkspaceKey)"));
        assert!(repository.contains("persistToWorkspace(targetWorkspaceKey, resolved)"));
        assert!(repository.contains("commitPreparedWorkspaceLocked(prepared)"));
        assert!(repository
            .contains("Identity-changing workspace switch requires an atomic session transition."));
        let transition = repository
            .find("private suspend fun transitionWorkspaceAndSession")
            .expect("atomic transition helper");
        let transition_body = &repository[transition..];
        let prepare = transition_body
            .find("prepareWorkspaceLocked(targetWorkspaceKey)")
            .expect("prepare target");
        let persist_session = transition_body
            .find("persistSyncSession(session)")
            .expect("persist matching session");
        let commit = transition_body
            .find("commitPreparedWorkspaceLocked(prepared)")
            .expect("commit target");
        assert!(prepare < persist_session && persist_session < commit);
        assert!(transition_body.contains("publishUndurableSyncFailure()"));
        let logout = repository
            .find("val localLogoutCommitted = writeMutex.withLock")
            .expect("logout transaction");
        let logout_body = &repository[logout..transition];
        assert!(
            logout_body
                .find("prepareWorkspaceLocked(guestWorkspaceKey)")
                .unwrap()
                < logout_body
                    .find("SecureSyncSessionStore.persistAfterLogout")
                    .unwrap()
        );
        assert!(
            logout_body
                .find("SecureSyncSessionStore.persistAfterLogout")
                .unwrap()
                < logout_body.find("commitPreparedWorkspaceLocked").unwrap()
        );
    }

