    #[test]
    fn guest_account_seed_fails_closed_until_every_referenced_blob_is_verified() {
        let media = source("com/ofairyo/gridtimer/data/NoteMediaStore.kt");
        let repository = source("com/ofairyo/gridtimer/data/TimerRepository.kt");

        let copy_start = media
            .find("fun copyReferencedAttachments(")
            .expect("workspace media copy helper");
        let copy_end = media[copy_start..]
            .find("fun resolvedAttachmentHashes(")
            .map(|offset| copy_start + offset)
            .expect("bounded workspace media copy helper");
        let copy_body = &media[copy_start..copy_end];
        let source_preflight = copy_body
            .find("role = \"Source\"")
            .expect("every source reference must be preflighted");
        let first_publish = copy_body
            .find("AtomicFileStore.replaceWithSyncedFile(target, temporary)")
            .expect("verified target publication");
        let final_target_verification = copy_body
            .rfind("role = \"Final target\"")
            .expect("all target references must be re-verified");
        assert!(source_preflight < first_publish && first_publish < final_target_verification);
        assert!(copy_body.contains("val referencedAttachments = attachments.toList()"));
        assert!(!copy_body.contains("if (!source.isFile)"));
        assert!(copy_body.contains("temporary.length() == attachment.sizeBytes"));
        assert!(copy_body.contains("sha256(temporary) == expectedDigest"));

        let verifier_start = copy_body
            .find("private fun requireVerifiedWorkspaceSeedAttachment(")
            .expect("strict workspace seed verifier");
        let verifier = &copy_body[verifier_start..];
        assert!(verifier.contains("attachment.fileName.isNotBlank()"));
        assert!(verifier.contains("attachment.sizeBytes > 0L"));
        assert!(verifier.contains("sha256Regex.matches(expectedDigest)"));
        assert!(verifier.contains("file.isFile"));
        assert!(verifier.contains("file.length() == attachment.sizeBytes"));
        assert!(verifier.contains("sha256(file) == expectedDigest"));

        let seed_start = repository
            .find("private fun seedNewAccountWorkspaceFromGuestIfAbsent(")
            .expect("guest-to-account seed helper");
        let seed_end = repository[seed_start..]
            .find("private suspend fun switchWorkspaceForSession(")
            .map(|offset| seed_start + offset)
            .expect("bounded guest-to-account seed helper");
        let seed_body = &repository[seed_start..seed_end];
        assert!(!seed_body.contains("runCatching"));
        let verified_copy = seed_body
            .find("NoteMediaStore.copyReferencedAttachments(")
            .expect("verified media copy must gate the seed");
        for durable_commit in [
            "stateDatabase.writeSnapshot(",
            "writeWorkspaceInitializationEvidence(targetWorkspaceKey)",
            "AtomicFileStore.writeText(target.state, selected.raw)",
            "AtomicFileStore.writeText(target.backup, selected.raw)",
        ] {
            assert!(
                verified_copy
                    < seed_body
                        .find(durable_commit)
                        .unwrap_or_else(|| panic!("missing target seed commit: {durable_commit}"))
            );
        }
        let retry_gate = &seed_body[..verified_copy];
        assert!(retry_gate.contains("stateDatabase.readSnapshots(targetWorkspaceKey)"));
        assert!(retry_gate.contains("readPersistedCandidate(target.state)"));
        assert!(retry_gate.contains("readPersistedCandidate(target.backup)"));
        assert!(!retry_gate.contains("mediaDirectory("));

        let auth_seed = repository[..seed_start]
            .rfind("seedNewAccountWorkspaceFromGuestIfAbsent(finalSession)")
            .expect("registration seed call");
        let auth_failure_gate = &repository[auth_seed..seed_start];
        assert!(auth_failure_gate.contains("}.isSuccess"));
        assert!(auth_failure_gate.contains("if (!guestDurableBeforeSeed)"));
    }

