    #[test]
    fn automatic_account_sync_uses_normal_sync_with_bounded_nonqueueing_retries() {
        let models = source("com/ofairyo/gridtimer/data/Models.kt");
        let repository = source("com/ofairyo/gridtimer/data/TimerRepository.kt");
        let screen = source("com/ofairyo/gridtimer/ui/GridTimerScreen.kt");
        let view_model = source("com/ofairyo/gridtimer/ui/TimerViewModel.kt");

        assert!(models.contains("val lastAutomaticSyncAttemptAtEpochMillis: Long = 0L"));
        let bootstrap_start = repository
            .find("private val accountBootstrapJob = scope.launch")
            .expect("account bootstrap job");
        let bootstrap_end = repository[bootstrap_start..]
            .find("private val pendingRevocationRetryJob")
            .map(|offset| bootstrap_start + offset)
            .expect("bounded account bootstrap job");
        let bootstrap = &repository[bootstrap_start..bootstrap_end];
        assert!(bootstrap.contains("syncAutomaticallyIfDue(AutomaticAccountSyncTrigger.STARTUP)"));
        assert!(!bootstrap.contains("downloadAccountDataToPhoneLocked"));
        assert!(!bootstrap.contains("hasVisibleAccountData"));

        let automatic_start = repository
            .find("suspend fun syncAutomaticallyIfDue(")
            .expect("automatic normal sync entry");
        let automatic_end = repository[automatic_start..]
            .find("private suspend fun syncNowLocked(")
            .map(|offset| automatic_start + offset)
            .expect("bounded automatic normal sync entry");
        let automatic = &repository[automatic_start..automatic_end];
        let try_lock = automatic
            .find("accountSyncMutex.tryLock()")
            .expect("automatic sync must not queue behind another account operation");
        let durable_attempt = automatic
            .find("session.copy(lastAutomaticSyncAttemptAtEpochMillis = wallNow)")
            .expect("automatic sync must durably mark its attempt");
        let normal_sync = automatic
            .find("syncNowLocked()")
            .expect("automatic entry must use ordinary merge sync");
        assert!(try_lock < durable_attempt && durable_attempt < normal_sync);
        assert!(automatic.contains("accountSyncMutex.unlock()"));
        assert!(automatic.contains("session.lastSyncAtEpochMillis"));
        assert!(automatic.contains("session.restoreReceipt.isBlank()"));
        assert!(
            repository.contains("private const val AUTOMATIC_SYNC_RETRY_COOLDOWN_MILLIS = 30_000L")
        );
        assert!(repository
            .contains("private const val AUTOMATIC_SYNC_SUCCESS_INTERVAL_MILLIS = 5 * 60_000L"));
        assert!(repository.contains("private const val MAX_NORMAL_SYNC_CONTINUATIONS = 2"));
        assert!(repository.contains("continueNormalSyncLocked(remainingContinuations)"));
        assert!(repository.contains("scheduleNormalSyncRetryAfterCooldown(remainingContinuations)"));
        assert!(repository.contains("syncNowLocked(remainingContinuations - 1)"));
        assert!(repository.contains("normalSyncRetryRequired = !snapshotDurable"));
        assert!(repository.contains("lastSyncAtEpochMillis = if (snapshotDurable) now() else 0L"));

        let root_start = screen.find("fun GridTimerRoot(").expect("root screen");
        let root_end = screen[root_start..]
            .find("private fun AmbientBackdrop(")
            .map(|offset| root_start + offset)
            .expect("bounded root screen");
        let root = &screen[root_start..root_end];
        assert!(
            root.contains("Lifecycle.Event.ON_START -> latestViewModel.syncAutomaticallyIfDue(")
        );
        assert!(!root.contains("Lifecycle.Event.ON_RESUME"));
        assert!(root.contains("AutomaticAccountSyncTrigger.FOREGROUND"));
        assert!(root.contains("if (selectedDestination == HomeNavigationDestination.MY)"));
        assert!(root.contains("while (isActive)"));
        assert!(root.contains("AutomaticAccountSyncTrigger.MY_PAGE"));
        assert!(root.contains("delay(30_000L)"));
        assert!(
            view_model.contains("fun syncAutomaticallyIfDue(trigger: AutomaticAccountSyncTrigger)")
        );
    }

