    #[test]
    fn account_snapshot_application_uses_the_shared_merger_and_rejects_stale_replacements() {
        let bridge = source("com/ofairyo/gridtimer/core/NativeOptimizerBridge.kt");
        let repository = source("com/ofairyo/gridtimer/data/TimerRepository.kt");
        assert!(bridge.contains("fun mergeSyncAppDataJson("));
        assert!(bridge.contains("nativeMergeSyncAppDataJson("));
        assert!(bridge.contains("private external fun nativeMergeSyncAppDataJson("));
        assert!(repository.contains("mergeAccountSnapshotWithCanonicalEngine("));
        assert!(repository.contains("NativeOptimizerBridge.mergeSyncAppDataJson("));
        assert_eq!(
            repository.matches("val requestApplyExpectation =").count(),
            3
        );
        assert_eq!(
            repository
                .matches("forceReplaceExpectation = applyExpectation")
                .count(),
            3
        );
        assert_eq!(
            repository
                .matches("!accountSnapshot.supersededByLocalChange")
                .count(),
            3
        );
        for (start_marker, end_marker) in [
            (
                "private suspend fun syncNowLocked(",
                "suspend fun uploadLocalDataToAccount()",
            ),
            (
                "private suspend fun uploadLocalDataToAccountLocked()",
                "suspend fun downloadAccountDataToPhone()",
            ),
            (
                "private suspend fun downloadAccountDataToPhoneLocked(",
                "fun flushNowBlocking(",
            ),
        ] {
            let start = repository
                .find(start_marker)
                .unwrap_or_else(|| panic!("missing account request body: {start_marker}"));
            let end = repository[start..]
                .find(end_marker)
                .map(|offset| start + offset)
                .unwrap_or_else(|| panic!("unbounded account request body: {start_marker}"));
            let body = &repository[start..end];
            let capture = body
                .find("val requestApplyExpectation = AccountSnapshotApplyExpectation(")
                .expect("request snapshot expectation");
            let network = body
                .find("val resultJson = withContext(Dispatchers.IO)")
                .expect("account network request");
            let apply = body
                .find("forceReplaceExpectation = applyExpectation")
                .expect("response apply expectation");
            assert!(capture < network && network < apply);
            assert!(body.contains("!decodedSnapshot.supersededByLocalChange"));
            assert!(body.contains("!accountSnapshot.supersededByLocalChange"));
        }
        let normal_sync_start = repository
            .find("private suspend fun syncNowLocked(")
            .expect("normal sync body");
        let normal_sync_end = repository[normal_sync_start..]
            .find("suspend fun uploadLocalDataToAccount()")
            .map(|offset| normal_sync_start + offset)
            .expect("bounded normal sync body");
        assert!(repository[normal_sync_start..normal_sync_end]
            .contains("normalSyncRetryRequired = !snapshotDurable"));
        let apply_start = repository
            .find("private suspend fun applyAccountSnapshotIfVisible(")
            .expect("account snapshot application helper");
        let apply_end = repository[apply_start..]
            .find("private fun historyDeletionSummaryText(")
            .map(|offset| apply_start + offset)
            .expect("bounded account snapshot application helper");
        let apply = &repository[apply_start..apply_end];
        let compare_and_swap = apply
            .find("_appData.value != forceReplaceExpectation.appData")
            .expect("force replacement compare-and-swap guard");
        let cancel_pending_write = apply
            .find("pendingPersistJob?.cancel()")
            .expect("pending write cancellation");
        assert!(compare_and_swap < cancel_pending_write);
        assert!(
            apply.contains("effectiveForceReplace &&\n                !recoveringMissingWorkspace")
        );
        assert!(apply.contains("activeWorkspaceKey != forceReplaceExpectation.workspaceKey"));
        assert!(apply.contains("supersededByLocalChange = true"));
        let superseded_return = apply
            .find("if (supersededByLocalChange)")
            .expect("superseded replacement return");
        let generic_persist_failure = apply
            .find("if (!persisted)")
            .expect("generic persist failure handling");
        let media_prune = apply
            .find("pruneNoteMedia(applied)")
            .expect("media pruning after durable apply");
        assert!(
            superseded_return < generic_persist_failure && generic_persist_failure < media_prune
        );
        assert!(
            !apply[superseded_return..generic_persist_failure].contains("schedulePersistRetry()")
        );
        let non_force_merge = apply
            .find("mergeAccountSnapshotWithCanonicalEngine(\n                    _appData.value,\n                    received")
            .expect("shared merger in non-force branch");
        assert!(cancel_pending_write < non_force_merge);
        assert!(repository.contains("同步期间本机数据已更新，已取消覆盖，请再次同步"));
    }

