    #[test]
    fn automatic_sync_prefers_public_discovery_and_preserves_last_good_route() {
        let route = source("com/ofairyo/gridtimer/data/SyncNetworkRoute.kt");
        let repository = source("com/ofairyo/gridtimer/data/TimerRepository.kt");
        let resolver_start = route
            .find("fun resolveServerUrl(")
            .expect("automatic route resolver must exist");
        let resolver_end = route[resolver_start..]
            .find("fun storedServerUrlForAutomaticMode(")
            .map(|offset| resolver_start + offset)
            .expect("automatic route resolver must have a bounded body");
        let resolver = &route[resolver_start..resolver_end];
        let remembered_public = resolver
            .find("verifiedRememberedPublicServerUrlOrNull(lastResolved")
            .expect("remembered public route must be attempted");
        let signed_public = resolver
            .find("SyncRemoteRendezvous.candidates(log)")
            .expect("signed remote rendezvous must be attempted");
        let packaged_public = resolver
            .find("publicServerUrlOrNull(BOOTSTRAP_PUBLIC_SYNC_SERVER_URL)")
            .expect("packaged public route must remain a fallback");
        let beacon = resolver
            .find("beaconReachableServerUrlOrNull(context, log)")
            .expect("LAN beacon must remain a fallback");
        let scan = resolver
            .find("discoverLocalServerUrl(context, log)")
            .expect("LAN subnet scan must remain a fallback");
        assert!(signed_public < packaged_public);
        assert!(packaged_public < remembered_public);
        assert!(remembered_public < beacon);
        assert!(beacon < scan);
        assert!(resolver.contains("if (discoveryIdentity != null)"));
        assert!(route.contains("手机无需与电脑连接同一局域网"));
        assert!(route.contains("newFixedThreadPool(minOf(64, candidates.size))"));
        assert!(route.contains("fastLocalProbe -> 350"));
        assert!(route.contains("connection.instanceFollowRedirects = false"));
        assert!(route.contains("readBoundedResponseBody(connection, HEALTH_RESPONSE_MAX_BYTES)"));
        assert!(route.contains("val attemptCount = if (publicProbe) 3 else 1"));
        assert!(route.contains("Thread.sleep(150L * (attempt + 1))"));
        assert!(route
            .contains("readBoundedResponseBody(connection, DISCOVERY_PROOF_RESPONSE_MAX_BYTES)"));
        assert!(route.contains("prefixLength.takeIf { it in 24..30 } ?: 24"));
        assert!(!repository.contains("withoutStaleAutomaticRoute"));
        assert!(!repository.contains("session.copy(lastResolvedServerUrl = \"\")"));
        assert!(repository.contains("routeFailureSession(session, message)"));
    }

    #[test]
    fn durable_note_upsert_updates_and_persists_in_one_repository_transaction() {
        let repository = source("com/ofairyo/gridtimer/data/TimerRepository.kt");
        let regular_start = repository
            .find("suspend fun upsertNote(note: NoteEntry, expectedWorkspaceKey: String): Boolean")
            .expect("regular note upsert must report whether the mutation was accepted");
        let durable_start = repository
            .find("suspend fun upsertNoteDurably(")
            .expect("durable note upsert must exist");
        let helper_start = repository
            .find("private fun upsertNoteInData(")
            .expect("note upserts must share one data transform");
        let next_api = repository[helper_start..]
            .find("suspend fun setNotePinned(")
            .map(|offset| helper_start + offset)
            .expect("durable upsert section must be bounded by the next repository API");

        let regular = &repository[regular_start..durable_start];
        let durable = &repository[durable_start..helper_start];
        let helper = &repository[helper_start..next_api];

        assert!(regular
            .contains("return updateData(expectedWorkspaceKey = expectedWorkspaceKey) { data ->"));
        assert!(regular.contains("upsertNoteInData(data = data, note = note, timestamp = now())"));
        assert!(durable.contains("val updateAttempt = withContext(NonCancellable)"));
        assert!(durable.contains("updateDataDetailed("));
        assert!(durable.contains("expectedWorkspaceKey = workspaceKey"));
        assert!(durable.contains("persistImmediately = true"));
        assert!(durable.contains("upsertNoteInData(data = data, note = note, timestamp = now())"));
        assert!(durable.contains("draftCheckpoint: NoteDraftJournalCheckpoint? = null"));
        assert!(durable.contains("committedNote = committedNote"));
        assert!(durable.contains("checkpoint = draftCheckpoint"));
        assert!(durable.contains("NoteSaveResult.journaled"));
        assert!(durable.contains("restoreJournaledNoteForCurrentSession"));
        assert!(!durable.contains("flushNow("));
        assert!(helper.contains("NativeOptimizerBridge.upsertNoteAppDataJson("));
        assert!(helper.contains("normalizeNoteForSave("));
    }

