        assert!(models.contains("val protectionStateRevision: Long = 0L"));
        assert!(models.contains("fun NoteEntry.effectiveProtectionStateRevision()"));
        assert!(models.contains("fun NoteEntry.hasAeadCiphertextRecoveryEnvelope()"));
        assert!(view_model.contains("protectionStateRevision = previousProtectionRevision + 1L"));
        assert!(view_model.contains("password.codePointCount(0, password.length) !in 8..128"));
        assert!(view_model.contains("newPassword.codePointCount(0, newPassword.length) !in 8..128"));
        assert!(note_ui.contains("password.codePointCount(0, password.length) < 8"));
        assert!(note_ui.contains("password.codePointCount(0, password.length) >= 8"));

        let password_change_start = view_model
            .find("fun changeEncryptedNotePassword(")
            .expect("password-change flow must exist");
        let disable_start = view_model[password_change_start..]
            .find("fun disableNoteEncryption(")
            .map(|offset| password_change_start + offset)
            .expect("password-change flow must be bounded");
        let password_change = &view_model[password_change_start..disable_start];
        let durable_save = password_change
            .find("repository.upsertNoteDurably(")
            .expect("password candidate must be durably saved");
        let commit = password_change
            .find("commitEncryptedNotePasswordChange(")
            .expect("durable password candidate must be committed");
        assert!(durable_save < commit);
        assert!(password_change.contains("val candidateResolved = AtomicBoolean(false)"));
        assert!(password_change.contains("fun abortPreparedCandidate()"));
