    #[test]
    fn note_creation_keeps_a_pending_draft_until_durable_upsert_is_visible() {
        let studio = source("com/ofairyo/gridtimer/ui/NoteStudioSheet.kt");
        let document_start = studio
            .find("internal fun NoteStudioSheet(")
            .expect("document note studio");
        let sticky_start = studio
            .find("internal fun StickyNoteStudioSheet(")
            .expect("sticky note studio");
        let builders_start = studio
            .find("internal fun buildPresetNote(")
            .expect("note preset builders");
        let document_studio = &studio[document_start..sticky_start];
        let sticky_studio = &studio[sticky_start..builders_start];

        for (label, body) in [("document", document_studio), ("sticky", sticky_studio)] {
            assert!(
                body.contains(
                    "var pendingCreatedNote by remember { mutableStateOf<NoteEntry?>(null) }"
                ),
                "{label} studio must retain a just-created note locally"
            );
            assert!(
                body.contains("?: pendingCreatedNote?.takeIf"),
                "{label} editor must resolve the pending note before repository publication"
            );
            assert!(
                body.contains("if (appData.notes.any { note -> note.id == pendingId })"),
                "{label} studio must clear the pending note after repository publication"
            );
            assert!(body.contains("LaunchedEffect(selectedNoteId, selectedNote)"));

            let create_start = body
                .find("onCreateNote = { preset ->")
                .unwrap_or_else(|| panic!("missing {label} create callback"));
            let create_body = &body[create_start..];
            let pending = create_body
                .find("pendingCreatedNote = freshNote")
                .expect("pending draft assignment");
            let selected = create_body
                .find("selectedNoteId = freshNote.id")
                .expect("editor selection assignment");
            let upsert = create_body
                .find("viewModel.upsertNoteAndFlushResult(")
                .expect("durable note upsert");
            assert!(
                pending < selected && selected < upsert,
                "{label} studio must retain the draft while its first durable write completes"
            );
        }
    }

