    #[test]
    fn sticky_note_toolbar_keeps_the_six_requested_actions_and_adapts_to_small_widths() {
        let screen = source("com/ofairyo/gridtimer/ui/GridTimerScreen.kt");
        let toolbar_start = screen
            .find("internal fun NoteEditorKeyboardToolbar(")
            .expect("note keyboard toolbar");
        let toolbar_end = screen[toolbar_start..]
            .find("internal fun NoteEditorToolbarButton(")
            .map(|offset| toolbar_start + offset)
            .expect("toolbar button after toolbar");
        let toolbar = &screen[toolbar_start..toolbar_end];

        let labels = ["标题", "居中", "列表", "粗体", "引用", "待办"];
        let mut last_position = 0;
        for label in labels {
            let position = toolbar
                .find(&format!("\"{label}\""))
                .unwrap_or_else(|| panic!("missing toolbar action: {label}"));
            assert!(
                position >= last_position,
                "toolbar actions must keep their requested order"
            );
            last_position = position;
        }
        assert!(toolbar.contains("val scrollActions = fontScale >= 1.5f || maxWidth < 320.dp"));
        assert!(toolbar.contains("LazyRow("));
        assert!(toolbar.contains("horizontal = true"));
        assert!(toolbar.contains("modifier = Modifier.weight(1f)"));
    }

