    #[test]
    fn note_exit_serializes_writes_and_commits_lifecycle_drafts() {
        let editor = source("com/ofairyo/gridtimer/ui/SmartisanNoteUi.kt");
        let document_editor = source("com/ofairyo/gridtimer/ui/NoteDocumentEditor.kt");
        let view_model = source("com/ofairyo/gridtimer/ui/TimerViewModel.kt");
        let repository = source("com/ofairyo/gridtimer/data/TimerRepository.kt");

        assert!(editor.contains("DisposableEffect(lifecycleOwner, note.id)"));
        assert!(editor.contains("Lifecycle.Event.ON_STOP"));
        assert!(editor.contains("latestExitPersistence(\"note_editor_stopped\")"));
        assert!(editor.contains("latestExitPersistence(\"note_editor_disposed\")"));
        assert!(editor.contains(
            "reason = \"note_editor_back\",\n            deleteBlankDraft = true,\n            richSnapshot = richSnapshot"
        ));
        assert!(editor.contains("busyLabel = \"正在保存…\""));
        assert!(editor.contains("if (isSavingDraft)"));
        assert!(editor.contains("lastDurableExitDraft"));
        assert!(!editor.contains("val candidate = latestPreviewNote"));

        assert!(document_editor.contains("DisposableEffect(lifecycleOwner, note.id)"));
        assert!(document_editor.contains("latestExitPersistence(\"document_note_editor_stopped\")"));
        assert!(document_editor.contains(
            "reason = \"document_note_editor_back\",\n            deleteBlankDraft = true"
        ));
        assert!(document_editor.contains("isSavingDraft -> \"正在保存…\""));
        assert!(document_editor.contains("val document = NoteDocument("));
        assert!(!document_editor.contains("val candidate = latestPreviewNote"));
        assert!(document_editor.contains("if (!requestedRevision.matches(note))"));

        assert!(view_model.contains("internal class NoteMutationDrainController("));
        assert!(view_model.contains("Channel<QueuedNoteMutation>(capacity = Channel.BUFFERED)"));
        assert!(view_model
            .contains("noteMutationScope = CoroutineScope(SupervisorJob() + Dispatchers.IO)"));
        assert!(view_model.contains("for (mutation in queue)"));
        assert!(view_model.contains("queue.close()\n            drainAbandonedMutations()"));
        assert!(view_model.contains("queue.trySend("));
        assert!(view_model.contains("shutdownRequested.compareAndSet(false, true)"));
        assert!(
            view_model.contains("queue.send(QueuedNoteMutation(flushOperation, flushCompletion))")
        );
        assert!(view_model.contains("noteMutationController.shutdownAfterDrain"));
        assert!(
            view_model.contains("repository.flushNow(\"viewmodel_cleared\", expectedWorkspaceKey)")
        );
        assert!(view_model.contains("Queued note mutation failed."));
        assert!(!view_model.contains("runNoteMutationBlocking"));
        assert!(!view_model.contains("withTimeoutOrNull(10_000L)"));
        assert!(!view_model.contains("runBlocking"));
        assert!(!view_model.contains("flushNowBlocking(reason = \"viewmodel_cleared\")"));
        assert!(view_model.contains("draftCheckpoint = draftCheckpoint"));
        assert!(view_model.contains("repository.deleteNotePermanently("));
        assert!(view_model.contains("expectedWorkspaceKey = expectedWorkspaceKey"));
        assert!(!view_model.contains("repository.deleteNotePermanently(noteId)\n            repository.flushNow(reason = reason)"));
        assert!(repository.contains("suspend fun upsertNoteDurably("));
        assert!(repository.contains("expectedWorkspaceKey: String? = null"));
    }

    #[test]
    fn rich_text_exit_waits_for_a_correlated_final_snapshot() {
        let editor = source("com/ofairyo/gridtimer/ui/SmartisanNoteUi.kt");
        let rich_editor = source("com/ofairyo/gridtimer/ui/NoteRichTextUi.kt");

        assert!(
            rich_editor.contains("fun onCommitSnapshot(requestId: String, payloadJson: String)")
        );
        assert!(rich_editor.contains("onCommitSnapshotResult(resolvedRequestId, snapshot)"));
        assert!(rich_editor.contains("function requestCommitSnapshot(requestId)"));
        assert!(rich_editor.contains(
            "window.AndroidRichText.onCommitSnapshot(String(requestId), JSON.stringify(payload));"
        ));
        assert!(rich_editor.contains("focusEditor,\n                        requestCommitSnapshot,\n                        setHtml"));
        assert!(
            rich_editor.contains("LaunchedEffect(webView, commitRequestId, controller.pageReady)")
        );
        assert!(rich_editor.contains("window.SmartisanRichText.requestCommitSnapshot(${JSONObject.quote(requestId.toString())});"));

        assert!(editor.contains("var richCommitRequestId by remember(note.id)"));
        assert!(editor.contains("commitRequestId = richCommitRequestId"));
        assert!(editor.contains("fun beginRichCommit(action: (RichTextEditorSnapshot) -> Unit) {\n        pendingRichCommitAction = action\n        nextRichCommitRequestId += 1L\n        richCommitRequestId = nextRichCommitRequestId\n    }"));
        assert!(editor.contains("if (richTextEnabled && showingLatestVersion) {\n            pendingRichCommitAction = { snapshot -> persistAndFinishBack(snapshot) }\n            nextRichCommitRequestId += 1L\n            richCommitRequestId = nextRichCommitRequestId\n            return\n        }\n        persistAndFinishBack()"));
        assert!(editor.contains("if (richCommitRequestId == requestId) {\n                                        richCommitRequestId = null\n                                        val action = pendingRichCommitAction\n                                        pendingRichCommitAction = null\n                                        action?.invoke(snapshot)"));

        let timeout_start = editor
            .find("LaunchedEffect(richCommitRequestId)")
            .expect("rich commit timeout guard");
        let timeout_end = editor[timeout_start..]
            .find("BackHandler(")
            .map(|offset| timeout_start + offset)
            .expect("back handler after timeout guard");
        let timeout_guard = &editor[timeout_start..timeout_end];
        assert!(timeout_guard.contains("delay(1_500L)"));
        assert!(timeout_guard.contains("富文本仍在同步，请稍后再试。"));
        assert!(!timeout_guard.contains("onBack()"));
        assert!(!timeout_guard.contains("persistAndFinishBack"));
    }

