    #[test]
    fn archive_restore_opens_only_the_durable_target_and_blocks_repeated_taps() {
        let screen = source("com/ofairyo/gridtimer/ui/GridTimerScreen.kt");
        let model = source("com/ofairyo/gridtimer/ui/TimerViewModel.kt");
        let repository = source("com/ofairyo/gridtimer/data/TimerRepository.kt");
        let restore = repository
            .split("    suspend fun restoreArchivedTask(")
            .nth(1)
            .unwrap()
            .split("    suspend fun deleteSession(")
            .next()
            .unwrap();
        assert!(restore.contains("publishAfterDurable = true"));
        assert!(restore.contains("target.accumulatedMillis == archivedTask.accumulatedMillis"));
        assert!(restore.contains("attempt.succeeded && targetSlotId != null"));
        assert!(restore.contains("attempt.snapshot!!.orderedSlots()"));
        assert!(model.contains("_archiveRestoreInProgress.compareAndSet(false, true)"));
        assert!(
            model.contains("repository.restoreArchivedTask(archivedTaskId, expectedWorkspaceKey)")
        );
        assert!(model.contains("currentWorkspaceKey() == expectedWorkspaceKey"));
        assert!(
            model.contains("finally {\n                _archiveRestoreInProgress.value = false")
        );
        assert!(
            screen.contains("viewModel.restoreArchivedTask(archivedTaskId) { slotId, message ->")
        );
        assert!(screen.contains(
            "if (slotId != null) {\n                                historyVisible = false"
        ));
        assert!(screen.contains("viewModel.openSlot(slotId)"));
        assert!(screen.contains("enabled = restoreTargetSlotId != null && !restoreInProgress"));
        assert!(screen.contains("restoreTargetDisplayNumber.toString().padStart(2, '0')"));
    }

    #[test]
    fn logout_revocation_queue_keeps_every_unconfirmed_token_and_is_keystore_encrypted() {
        let secure_store = source("com/ofairyo/gridtimer/data/SecureLocalStore.kt");
        let repository = source("com/ofairyo/gridtimer/data/TimerRepository.kt");
        assert!(secure_store.contains("val pendingRevocations: List<PendingTokenRevocation>"));
        let sanitize_start = secure_store
            .find("private fun sanitizePendingRevocations(")
            .expect("pending revocation sanitizer");
        let sanitize_end = secure_store[sanitize_start..]
            .find("private fun upsertAccountSyncCheckpoint(")
            .map(|offset| sanitize_start + offset)
            .expect("bounded pending revocation sanitizer");
        let sanitize = &secure_store[sanitize_start..sanitize_end];
        assert!(sanitize
            .contains("distinctBy { revocation -> revocation.userId to revocation.tokenId }"));
        assert!(sanitize.contains("sortedBy(PendingTokenRevocation::createdAtEpochMillis)"));
        assert!(!sanitize.contains("takeLast("));
        assert!(!secure_store.contains("MAX_PENDING_REVOCATIONS"));
        assert!(repository.contains("account_logout_before_request"));
        assert!(repository.contains("本机已退出，服务器会话未确认撤销"));
        assert!(repository.contains("SecureSyncSessionStore.persistAfterLogout"));
        assert!(repository.contains("retryPendingLogoutRevocations"));
    }
